-- Dansk portion 9 del 2/3: 167 MC-spørgsmål på sværhedsskalaen 1-10.000, niveau 3344-6576.
-- Del af de 5.000 nye danskopgaver. Skrevet fra bunden til dansk folkeskole, 3.-9. klasse.
-- Genereret af tools/questions/build-danish-5000.mjs; ret i tools/questions/fixtures/danish-5000/, ikke her.
-- Kræver migration A (20261020120000_difficulty_scale_a): kolonnen questions.difficulty_level.
--
-- Niveau: hver opgave har et eksplicit difficulty_level (forfatterens skøn, ikke en måling).
-- target_grade/difficulty_band er afledt baglæns af niveauet (cellen i §4.1).
--
-- INAKTIV VED INDSÆTTELSEN: alle rækker får is_active=false og metadata.level_batch='danish9'.
-- Aktivering er en SEPARAT migration efter dokumenteret stikprøvekontrol og særskilt ejergodkendelse.
-- Må KUN anvendes via apply_migration med særskilt ejer-autorisation (D-110).

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band, difficulty_level)
SELECT
  jsonb_build_object('question', e->>'q', 'options', e->'o', 'correct', e->>'a',
                     'accepted_answers', jsonb_build_array(e->>'a'), 'review_text', e->>'r'),
  'mc', 'short',
  jsonb_build_object('concepts', jsonb_build_array(m.concept), 'cognitive_skill', m.skill,
                     'difficulty_type', m.dtype, 'misconception_type', m.mis,
                     'challenge_role', e->>'role', 'insight_type', e->>'insight',
                     'practice_variant', e->>'variant',
                     'level_batch', 'danish9', 'domain', 'danish'),
  'mc_single', (e->>'b')::int, 'auto', false, 'danish', (e->>'g')::int,
  (e->>'b')::int, (e->>'l')::int
FROM jsonb_array_elements($$[
{"l":3344,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'I de gamle ___ film kunne man ikke høre skuespillerne tale.'","o":["stume","stummer","stumne","stumme"],"a":"stumme","r":"Grundformen er 'stum'. Når der kommer en endelse på efter kort vokal, fordobles m'et."},
{"l":3366,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sæt 'at fortsætte' i datid: 'Hele aftenen ___ vi med at spille kort.'","o":["fortsatte","fortsætter","fortsat","fortsætte"],"a":"fortsatte","r":"'At fortsætte' skifter vokal ligesom 'at sætte': fortsætter, fortsatte, har fortsat. Datid er 'fortsatte'."},
{"l":3388,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at bære' passer: 'Du har ___ den tunge kasse hele vejen.'","o":["bar","båret","bærer","bære"],"a":"båret","r":"Efter 'har' står tillægsformen, og af 'at bære' hedder den 'båret'. 'Bar' er datid."},
{"l":3407,"g":5,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad gør en elev, der 'springer over, hvor gærdet er lavest'?","o":["Er god til højdespring","Løber væk fra en have","Vælger den nemmeste løsning","Gør det sværeste først"],"a":"Vælger den nemmeste løsning","r":"Hvor gærdet er lavest, er det lettest at komme over. Vendingen bruges om dem, der gør så lidt som muligt."},
{"l":3432,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken tid står sætningen i: 'Clara havde glemt sin madkasse.'","o":["førnutid","datid","nutid","førdatid"],"a":"førdatid","r":"'Havde' plus tillægsform giver førdatid. Det bruges om noget, der skete før et andet tidspunkt i fortiden."},
{"l":3450,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Til alle, der bruger cykelkælderen: Der er i den sidste tid sat mange cykler på gulvet foran døren. Det gør det svært at komme ind og ud, og ved brand er det farligt. Sæt derfor din cykel i stativerne. Cykler uden for stativerne bliver flyttet ud i gården. Bestyrelsen' Hvad er tonen i opslaget?","o":["Bestemt, men rolig","Hyggelig og spøgefuld","Venlig og spørgende","Rasende og truende"],"a":"Bestemt, men rolig","r":"Opslaget forklarer problemet og siger klart, hvad man skal gøre, uden at skælde ud."},
{"l":3468,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skal skoledagen starte senere? Mange unge sover for lidt. Forskere mener, at unge er trætte om morgenen, fordi deres kroppe er indstillet på at gå sent i seng. Jeg synes derfor, at skolen burde begynde klokken ni. Så ville vi lære meget mere.' Hvad vil skribenten overbevise læseren om?","o":["At unge bør gå tidligere i seng om aftenen","At skolen bør starte senere om morgenen","At forskere bør undersøge søvn hos unge mere","At skolens lærere bør give færre lektier for"],"a":"At skolen bør starte senere om morgenen","r":"Skribenten bruger forskningen som argument for sin egen holdning: Skolen burde starte klokken ni."},
{"l":3487,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Hun er den ___ i klassen, for hun har fødselsdag i januar.'","o":["ælste","ældeste","ældste","eldste"],"a":"ældste","r":"Ordet er højeste grad af 'gammel'. D'et skal med, selvom det ikke høres, og der er ikke noget e mellem d og s."},
{"l":3509,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken form mangler? 'Hvem har ___ klistermærker i albummet?'","o":["flæst","flerest","flesst","flest"],"a":"flest","r":"Ordet er højeste grad af 'mange'. Det staves med e og har kun ét s."},
{"l":3530,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Et komma er for meget i: 'Jeg så Ida, Ali, Malthe, og Sara i biografen.' Efter hvilket navn skal det væk?","o":["Malthe","Ida","Ali","Sara"],"a":"Malthe","r":"Der står komma mellem navnene i opremsningen, men ikke foran 'og'. Derfor skal kommaet efter 'Malthe' væk."},
{"l":3549,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal der komma: 'Eftersom det var sidste skoledag fik vi lov at se film.'?","o":["sidste","skoledag","fik","lov"],"a":"skoledag","r":"'Eftersom det var sidste skoledag' er en ledsætning, der forklarer hvorfor. Den slutter med 'skoledag'."},
{"l":3567,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fredag åbnede Skovlunds Skole en ny skolehave. Eleverne har selv sået gulerødder og kartofler. Skolehaven er det bedste, skolen har gjort i mange år, skriver skolebladet. Haven er betalt af et lokalt legat, og den bliver passet af elever fra 4. og 5. klasse.' Hvilken oplysning er IKKE et faktum?","o":["Haven er betalt af et lokalt legat","Eleverne har selv sået gulerødder","Haven er det bedste, skolen har gjort","Haven bliver passet af 4. og 5. klasse"],"a":"Haven er det bedste, skolen har gjort","r":"'Det bedste' er en vurdering, og skolebladet giver her sin holdning. Resten kan man tjekke."},
{"l":3586,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Sara så Hassan i gården. Hvilket ord passer: 'Hassan opdagede ikke, at Sara vinkede til ___.'","o":["han","sig","hans","ham"],"a":"ham","r":"Efter 'til' skal der stå 'ham', for det er Hassan, hun vinker til. 'Sig' ville pege tilbage på Sara, som er grundled i ledsætningen."},
{"l":3606,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken del er ledsætningen i: 'Hvis vi skynder os, når vi bussen.'?","o":["Hvis vi skynder os","vi skynder os","når vi bussen","Hvis vi"],"a":"Hvis vi skynder os","r":"Ledsætningen indledes med 'hvis' og går helt hen til kommaet. 'når' er her et udsagnsord i hovedsætningen og ikke et bindeord."},
{"l":3625,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal det første komma stå: 'Når vi holder fri spiser vi pizza ser film og spiller spil.'?","o":["pizza","fri","film","spil"],"a":"fri","r":"Først skal ledsætningen 'Når vi holder fri' skilles fra resten. Bagefter kommer et komma efter 'pizza' i opremsningen."},
{"l":3644,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort: 'På turen til København så vi rundetårn og en gammel kirke.'?","o":["turen","kirke","rundetårn","gammel"],"a":"rundetårn","r":"Rundetårn er navnet på en bestemt bygning i København, så det skal have stort bogstav."},
{"l":3663,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket forholdsord hører til: 'Lillesøster er helt afhængig ___ sin bamse.'","o":["på","til","med","af"],"a":"af","r":"På dansk siger man 'afhængig af': afhængig af hjælp, afhængig af sin bamse. Den slags ordpar må man lære udenad."},
{"l":3685,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er det modsatte af 'ubetydelig' i sætningen: 'Det var en ubetydelig fejl.'","o":["alvorlig","sjælden","gammel","tilfældig"],"a":"alvorlig","r":"En ubetydelig fejl betyder næsten ingenting. En alvorlig fejl får store følger."},
{"l":3701,"g":5,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Efter ferien i italien lærte vi lidt italiensk.'?","o":["ferien","italien","lærte","italiensk"],"a":"italien","r":"Italien er et land og skal have stort bogstav. Sproget italiensk skrives med lille."},
{"l":3722,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kalder biologer alle de ræve, der lever i det samme område?","o":["en fødekæde","et kredsløb","en population","et klima"],"a":"en population","r":"En population er alle dyr af samme art i et bestemt område. Ordet kommer af det latinske ord for folk."},
{"l":3745,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad er 'erosion'?","o":["at vulkaner sender aske højt op i luften","at jorden ryster, fordi store plader flytter sig","at floder fryser til is i løbet af vinteren","at vand og vind langsomt slider jord og sten væk"],"a":"at vand og vind langsomt slider jord og sten væk","r":"Erosion sker langsomt, men kan forme hele landskaber. Kysten bliver for eksempel gnavet væk af bølgerne."},
{"l":3762,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvem får noget? Find hensynsleddet: 'Vi købte vores lærer en buket blomster.'","o":["vores lærer","Vi","en buket blomster","købte"],"a":"vores lærer","r":"Blomsterne er til læreren, så 'vores lærer' er hensynsleddet. 'En buket blomster' er genstandsleddet."},
{"l":3784,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Anton står foran spejlet og kigger på sig selv. Hvilket ord passer: 'Anton ser ___ i spejlet.'","o":["ham","sig","han","hans"],"a":"sig","r":"Anton ser på sig selv, så ordet peger tilbage på grundleddet. Med 'ham' ville det være en anden dreng."},
{"l":3805,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad var en 'vasal' i middelalderen?","o":["en mand, der gik fra by til by og solgte varer på markeder","en mand, der boede i et kloster og skrev bøger af i hånden","en mand, der fik jord af en herre mod at love ham troskab","en mand, der vogtede kongens får på de store marker"],"a":"en mand, der fik jord af en herre mod at love ham troskab","r":"Vasallen fik et len, altså et stykke jord, af sin herre. Til gengæld skyldte han ham troskab og hjælp i krig."},
{"l":3825,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvem har skrevet bøgerne om Pippi Langstrømpe?","o":["Tove Jansson","Selma Lagerlöf","Karin Michaëlis","Astrid Lindgren"],"a":"Astrid Lindgren","r":"Astrid Lindgren var en svensk forfatter. Hun skrev også om Emil fra Lønneberg og Ronja Røverdatter."},
{"l":3842,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad kendetegner 'industrialiseringen'?","o":["Maskiner og fabrikker overtog meget af arbejdet","Bønderne fik lov til at købe deres egen gård","Danmark mistede mange af sine gamle landområder","Skolerne begyndte at undervise børn i sprog"],"a":"Maskiner og fabrikker overtog meget af arbejdet","r":"Med dampmaskinen og fabrikkerne blev mange varer lavet i store mængder, og folk flyttede ind til byerne for at arbejde."},
{"l":3861,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg datid af 'at vælge': 'I går ___ klassen to nye elever til elevrådet.'","o":["vælger","valgte","valgt","vælge"],"a":"valgte","r":"'At vælge' skifter vokal i datid: vælger, valgte, har valgt."},
{"l":3883,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad er rigtigt? 'Han har ___ rygsækken hele vejen op ad bakken.'","o":["bårret","bæret","båret","bærte"],"a":"båret","r":"Efter 'har' skifter æ til å, og der er kun ét r."},
{"l":3900,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Skolens nye regel: Alle skal aflevere deres mobil i et skab om morgenen. Reglen gælder også i frikvartererne.' Hvad svarer teksten ikke på?","o":["Hvor mobilen skal afleveres","Hvornår på dagen den skal afleveres","Om reglen også gælder i frikvartererne","Hvornår eleverne får mobilen tilbage"],"a":"Hvornår eleverne får mobilen tilbage","r":"Der står, hvor og hvornår mobilen afleveres, og at frikvartererne er med, men ikke hvornår den udleveres igen."},
{"l":3917,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvordan har man det, når man 'sidder med skægget i postkassen'?","o":["Man er kommet i en pinlig knibe","Man venter spændt på et brev","Man er blevet for gammel til noget","Man er ligeglad med det hele"],"a":"Man er kommet i en pinlig knibe","r":"Billedet er en, der har fået skægget i klemme og ikke kan komme fri. Man sidder fast i en situation uden udvej."},
{"l":3940,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad vil ordsproget 'Når man har sagt A, må man også sige B' fortælle?","o":["Man skal lære alfabetet i den rigtige rækkefølge","Har man begyndt på noget, må man også gøre det færdigt","Man skal altid svare, når andre stiller et spørgsmål","Har man sagt noget forkert, må man sige undskyld"],"a":"Har man begyndt på noget, må man også gøre det færdigt","r":"Ordsproget siger, at det, man har sat i gang, forpligter. Man må tage de næste skridt og følgerne med."},
{"l":3960,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige endelse: 'Den ___ pige vinkede til os fra perronen.'","o":["smilene","smilenne","smilende","smilendes"],"a":"smilende","r":"Lang tillægsform ender på -ende. D'et skal med, selvom man ikke hører det."},
{"l":3982,"g":5,"b":4,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Find biordet: 'Heldigvis nåede vi toget.'","o":["nåede","vi","toget","Heldigvis"],"a":"Heldigvis","r":"'Heldigvis' siger noget om hele sætningen og viser, hvad den talende synes. Det er et biord."},
{"l":4004,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Anders og ___ far bygger en båd.'","o":["hans","sin","sine","deres"],"a":"hans","r":"Spørg: Hvem bygger? Det gør 'Anders og hans far', og det hele er ét grundled. 'Sin' kan ikke stå inde i grundleddet."},
{"l":4023,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Referat fra elevrådsmøde. Til stede: 9 elever, Bente (lærer). Punkt 1: Kantinen. Der er ønske om flere vegetarretter, og Bente taler med køkkenet. Punkt 2: Julefest. Datoen bliver fredag d. 17. december. Næste møde: 11. januar.' Hvad er meningen med sådan en tekst?","o":["At underholde elever med en sjov historie","At holde styr på, hvad man har talt om","At overbevise køkkenet om at lave mere mad","At invitere alle på skolen til en julefest"],"a":"At holde styr på, hvad man har talt om","r":"Et referat fortæller kort, hvad der blev sagt og besluttet på et møde, så deltagerne kan huske det."},
{"l":4043,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Havde vi haft tid ville vi have besøgt dig.'?","o":["haft","ville","tid","besøgt"],"a":"tid","r":"'Havde vi haft tid' betyder 'hvis vi havde haft tid'. Det er en ledsætning uden bindeord, og den står først."},
{"l":4060,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvilket ord kan erstatte 'indebærer' her: 'Opgaven indebærer, at I skal interviewe en voksen.'","o":["forhindrer","forbyder","udsætter","medfører"],"a":"medfører","r":"Når noget indebærer noget andet, følger det med. Opgaven kan ikke løses uden interviewet."},
{"l":4081,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal have stort: 'Vi så stykket »kejserens nye klæder« på skolen.'?","o":["kejserens","nye","klæder","skolen"],"a":"kejserens","r":"'Kejserens nye klæder' er en titel, og i en titel får det første ord stort bogstav. De andre ord skrives med lille."},
{"l":4103,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad hedder et skema over, hvornår noget skal ske? Find den rigtige stavning.","o":["tidplan","tidsplan","tisplan","tidesplan"],"a":"tidsplan","r":"Ordet har fuge-s mellem 'tid' og 'plan', og d'et fra 'tid' skal med."},
{"l":4120,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad menes der med 'evolution' i biologi?","o":["at et dyr skifter pels, når årstiderne ændrer sig","at et lille dyr vokser op og bliver helt voksent","at arter langsomt ændrer sig gennem mange generationer","at dyr flytter til varmere lande, når de fryser"],"a":"at arter langsomt ændrer sig gennem mange generationer","r":"Evolution sker over meget lang tid, når egenskaber går videre fra forældre til unger. Det enkelte dyr udvikler sig ikke på den måde."},
{"l":4140,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sara stod øverst på vippen og så ned på vandet. Bag hende rykkede køen et skridt frem. Hun talte til tre, men begyndte forfra. – Jeg skal lige rette min badehætte, sagde hun til drengen bag sig.' Hvorfor nævner Sara sin badehætte?","o":["Hætten er gledet skævt på vej op ad stigen","Hun vil vise drengen, hvordan man gør klar til et spring","Hun er irriteret over, at køen rykker så hurtigt frem","Hun tør ikke springe endnu, men vil ikke vise det"],"a":"Hun tør ikke springe endnu, men vil ikke vise det","r":"Hun tæller forfra og bliver stående, så hætten er bare en undskyldning. Intet i teksten viser, at den sidder forkert."},
{"l":4158,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at springe' passer: 'Hesten er ___ over hegnet.'","o":["sprunget","sprang","springer","springe"],"a":"sprunget","r":"Efter 'er' danner tillægsformen 'sprunget' førnutid. 'Sprang' er datid."},
{"l":4180,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betød 'stavnsbåndet', der blev ophævet i 1788?","o":["at alle bønder skulle betale en ny skat til kongen hvert år","at unge mænd på landet ikke frit måtte flytte fra godset","at kvinder på landet ikke måtte arbejde uden for gården","at børn på landet skulle gå syv år i kirkens egne skoler"],"a":"at unge mænd på landet ikke frit måtte flytte fra godset","r":"Stavn betyder hjemsted. Stavnsbåndet bandt bøndernes sønner til det gods, de var født på. Ophævelsen var en vigtig del af landboreformerne."},
{"l":4200,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Lyset fra et lyn når os næsten med det samme, mens lyden kun bevæger sig cirka en kilometer på tre sekunder. Derfor kan man tælle sekunderne mellem lyn og torden.' Hvad kan man slutte, hvis der går ni sekunder fra lyn til torden?","o":["Lynet slog ned cirka ni kilometer væk","Uvejret er på vej væk fra den, der tæller sekunder","Lynet slog ned cirka tre kilometer væk","Der kommer snart et nyt lyn"],"a":"Lynet slog ned cirka tre kilometer væk","r":"Tre sekunder svarer til en kilometer, så ni sekunder svarer til cirka tre. Om uvejret er på vej væk, kan man ikke se af én måling."},
{"l":4217,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad siger det gamle ordsprog 'Hvo intet vover, intet vinder'?","o":["Man bør holde sig fra alle slags spil","Det er bedre at tabe end at snyde","De modige taber altid til sidst","Man skal turde noget for at opnå noget"],"a":"Man skal turde noget for at opnå noget","r":"Hvo er et gammelt ord for den, der, og vove betyder at turde. Ordsproget siger, at man må løbe en risiko for at vinde noget."},
{"l":4235,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg den rigtige stavning: 'Vi havde en ___ aften med brætspil.'","o":["hyggelig","hygelig","hyggeli","hygglig"],"a":"hyggelig","r":"Ordet har dobbelt g, fordi y'et er kort, og det ender på -lig."},
{"l":4257,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Find ordet: 'Jeg faldt på cyklen, men ___ slog jeg mig ikke.'","o":["helligvis","heldigvis","heldivis","heldigtvis"],"a":"heldigvis","r":"Ordet er 'heldig' plus -vis. Både d og g skal med, selvom g'et ikke høres."},
{"l":4279,"g":5,"b":5,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilket ord passer: 'Lukas ___ sig på bænken og tog sin bog frem.'","o":["sad","sidder","satte","siddet"],"a":"satte","r":"Det hedder 'at sætte sig', og datid er 'satte'. Først sætter han sig, og bagefter sidder han."},
{"l":4300,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'vand' i sætningen: 'Vand blomsterne i aften!'","o":["navneord","tillægsord","stedord","udsagnsord"],"a":"udsagnsord","r":"Sætningen er en opfordring, og 'vand' står i bydemåde af 'at vande'. Det er altså et udsagnsord."},
{"l":4320,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Noah så på sin ven Rasmus, som lige havde fået rollen som kaptajn på holdet. Han klappede med de andre. På vej hjem sparkede han til en sten hele vejen, og da far spurgte, hvordan træningen havde været, svarede han: – Det var fint. Rasmus er god til at råbe.' Hvad røber Noahs svar?","o":["At han misunder Rasmus og er skuffet","At han er stolt af sin vens gode stemme","At han gerne vil skifte til et andet hold","At han ikke har været til træning i dag"],"a":"At han misunder Rasmus og er skuffet","r":"Han klapper udadtil, men stenen og den lille stikpille om råb viser skuffelse og misundelse."},
{"l":4340,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Sønderholt Zoo har for første gang fået to sjældne fugleunger til at overleve. Før fik fuglene næsten kun én slags mad, men nu får de foder, der ligner det, de spiser i naturen. Chefen vil ikke love noget for fremtiden, men han er fortrøstningsfuld.' Hvad betyder det, at chefen er fortrøstningsfuld?","o":["At han er bange for, at det går galt","At han har håb om, at det vil gå godt","At han er sikker på, at det vil gå godt","At han er træt af at tale om det hele"],"a":"At han har håb om, at det vil gå godt","r":"Han vil ikke love noget, men er fortrøstningsfuld. Det betyder, at han tror på det uden at være sikker."},
{"l":4360,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Jo, klassen kan godt tage i forlystelsespark på næste klassetur. Det er sjovt, ja. Men jeg ved, hvad jeg ville vælge. Sidste år sov vi i telt ved søen, og vi taler stadig om natten, hvor det regnede ind.' Hvad ville skribenten vælge?","o":["At tage i forlystelsespark med klassen","At blive hjemme på skolen på turen","At sove i telt ved søen igen","At finde et sted, hvor det ikke regner"],"a":"At sove i telt ved søen igen","r":"Skribenten siger det ikke direkte, men klassen taler stadig om teltturen. Det viser, at det var den, der var bedst."},
{"l":4380,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Reklamen lover, at du får glat hud på syv dage. I reklamen står en kvinde i hvid kittel, og nederst står der med små bogstaver: Resultater kan variere. Kvinden ligner en læge, men hun er skuespiller. Reklamen skal vække tillid, uden at sige noget, der kan bevises.' Hvad er det, teksten vil lære læseren?","o":["At reklamer altid lyver om det, de sælger","At glat hud er noget, man kan få på syv dage","At læger ofte bruges i reklamer for hudcreme","At reklamer kan narre én til at stole på dem"],"a":"At reklamer kan narre én til at stole på dem","r":"Teksten afslører, hvordan reklamen bruger kittel og små bogstaver til at skabe tillid uden bevis."},
{"l":4400,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'væsentlig' i sætningen 'Der er en væsentlig forskel på de to bøger'?","o":["stor og vigtig","lille og næsten usynlig","mærkelig og uforklarlig","ny og spændende"],"a":"stor og vigtig","r":"Noget væsentligt er vigtigt for sagen. Det modsatte ville være noget uvæsentligt, altså ligegyldigt."},
{"l":4418,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Vælg stavemåden: 'Husk at købe en ___, før du går op i toget.'","o":["bilet","billet","billett","bilett"],"a":"billet","r":"Ordet har dobbelt l og kun ét t til sidst. Det er et fransk lånord."},
{"l":4438,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvornår 'går man som katten om den varme grød'?","o":["når man er meget sulten og utålmodig","når man bevæger sig stille og lydløst","når man undgår at tale direkte om det svære","når man venter på, at noget skal køle af"],"a":"når man undgår at tale direkte om det svære","r":"Talemåden beskriver en, der kredser om et emne, fordi det er ubehageligt at sige det lige ud."},
{"l":4460,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Læreren minder om, at opgavens 'deadline' er på fredag. Hvad er en deadline?","o":["den første dag, man må begynde på en opgave","en streg, som man ikke må træde over til prøven","en liste over de ting, man skal have med","det seneste tidspunkt, noget skal være færdigt"],"a":"det seneste tidspunkt, noget skal være færdigt","r":"Deadline er et engelsk låneord for en frist. Efter det tidspunkt er det for sent at aflevere."},
{"l":4478,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvad skal der stå? 'Vi målte, hvor varmt vandet var, med et ___.'","o":["termometer","termomether","thermometer","tærmometer"],"a":"termometer","r":"På dansk skrives ordet med t uden h. Det består af 'termo' og 'meter'."},
{"l":4498,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Vælg datid af 'at vride': 'Hun ___ kluden, så vandet dryppede af den.'","o":["vredet","vred","vrider","vride"],"a":"vred","r":"'Dryppede' står i datid, så det skal 'vride' også. 'At vride' bøjes vrider, vred, har vredet."},
{"l":4514,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Vi køber frokost i skolens ___.'","o":["kantinne","kanntine","kantine","kantiene"],"a":"kantine","r":"Ordet staves kan-ti-ne med ét n i første og ét n i sidste stavelse, og det ender på -ine."},
{"l":4535,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Efter flere timers forhandling nåede de to parter endelig til ___.'","o":["ansvar","modstand","overflod","enighed"],"a":"enighed","r":"En forhandling skal ende med en aftale. Når parterne når til enighed, er de blevet enige."},
{"l":4556,"g":6,"b":1,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Efter hvilket ord skal kommaet stå: 'Det var da en flot tegning Noor.'?","o":["tegning","da","en","flot"],"a":"tegning","r":"Når man taler direkte til en person, skilles navnet fra resten af sætningen med komma."},
{"l":4575,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Ved første øjekast ligner vandmanden en sæk uden indhold. Den har ingen hjerne, ingen knogler og intet hjerte. Alligevel har den levet i havene i mere end 500 millioner år, længere end dinosaurerne. Noget af det enkleste i naturen kan altså klare sig rigtig godt.' Hvad vil forfatteren vise med vandmanden?","o":["At vandmænd er meget klogere, end de fleste mennesker tror","At dyr godt kan klare sig, selvom de er enkelt bygget","At dinosaurerne var svagere end vandmænd","At vandmænd lever længere end andre dyr"],"a":"At dyr godt kan klare sig, selvom de er enkelt bygget","r":"Sidste sætning samler pointen: Vandmanden er enkelt bygget og har alligevel overlevet i meget lang tid."},
{"l":4597,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'om' i sætningen: 'Bogen handler om en tabt hvalp.'","o":["bindeord","biord","forholdsord","stedord"],"a":"forholdsord","r":"'Om' står foran 'en tabt hvalp' og hører sammen med den ordgruppe. Så er det et forholdsord."},
{"l":4610,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Sæt ind: 'Når hunden er syg, ringer vi efter en ___.'","o":["dyrelæge","dyrslæge","dyr læge","dyrlæge"],"a":"dyrlæge","r":"Ordet skrives i ét ord, og der er hverken e eller s mellem 'dyr' og 'læge'."},
{"l":4630,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken ordklasse har 'den' i sætningen: 'Den er for tung at løfte.'","o":["stedord","kendeord","talord","biord"],"a":"stedord","r":"'Den' står alene i stedet for et navneord. Et kendeord ville stå sammen med et navneord."},
{"l":4651,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken pris er skrevet rigtigt på skiltet i kantinen?","o":["12.50 kr.","12,50 kr.","12;50 kr.","12:50 kr."],"a":"12,50 kr.","r":"Kroner og øre adskilles med komma, fordi det er et decimaltal. 'Kr.' skrives med punktum."},
{"l":4670,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Det er farmoren til Thomas. Hvilken form er rigtig: 'Vi besøgte ___ farmor i Viborg.'?","o":["Thomas's","Thoma's","Thomas'","Thomass"],"a":"Thomas'","r":"Thomas ender på s, så ejefald skrives med en apostrof efter navnet."},
{"l":4689,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når Clara bliver tiltalt først i sætningen?","o":["Clara kan du hjælpe mig med at bære?","Clara kan du hjælpe, mig med at bære?","Clara kan, du hjælpe mig med at bære?","Clara, kan du hjælpe mig med at bære?"],"a":"Clara, kan du hjælpe mig med at bære?","r":"Når man tiltaler en person, skilles navnet fra resten af sætningen med komma."},
{"l":4705,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Hvis du har mistet din hue i biografen, kan du henvende dig i billetlugen. Glemte ting gemmes i 30 dage. Vi gør opmærksom på, at biografen ikke har ansvar for værdigenstande. Efter 30 dage bliver tøj doneret til velgørenhed, mens telefoner afleveres til politiet.' Hvad sker der med en telefon, der ligger uafhentet i 31 dage?","o":["Den bliver afleveret til politiet","Den bliver givet til velgørenhed","Den bliver i billetlugen, til nogen kommer","Den bliver sendt til biografens ejer"],"a":"Den bliver afleveret til politiet","r":"Teksten skelner mellem tøj og telefoner. Telefoner går til politiet efter 30 dage."},
{"l":4724,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvem er Birk i Astrid Lindgrens 'Ronja Røverdatter'?","o":["Ronjas far, der er røverhøvding","En dreng fra den fjendtlige røverbande","En gammel røver, der elsker sange","En vild hest, der lever frit i den dybe skov"],"a":"En dreng fra den fjendtlige røverbande","r":"Ronja og Birk bliver venner, selvom deres fædre er fjender. Bogen handler meget om deres venskab."},
{"l":4745,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Fuglebogen lå altid på bordet ved vinduet. Farfar havde skrevet dato og art for hver fugl, han havde set siden 1962. Mange sider handlede om sjældne ørne og traner. Men i dag stod der kun: Solsort. Sang i morges. Godt.' Hvad fortæller notitsen fra i dag om farfar?","o":["At han ved meget lidt om fugle","At han er ved at blive træt af fugle","At han også bliver glad for en almindelig fugl","At han er sur over, at solsorten sang så tidligt"],"a":"At han også bliver glad for en almindelig fugl","r":"Ordet 'Godt' er kort, men varmt. Farfar har set mange sjældne fugle, men han glæder sig stadig over en solsort."},
{"l":4765,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvor skal kommaet stå i 'Fordi bussen var forsinket kom vi for sent til timen.'?","o":["efter bussen","efter kom","efter vi","efter forsinket"],"a":"efter forsinket","r":"Ledsætningen 'Fordi bussen var forsinket' står først. Kommaet skal sættes, hvor den slutter."},
{"l":4784,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Hvad betyder 'dækker' i sætningen 'Forsikringen dækker skaden på cyklen'?","o":["betaler for","lægger noget over","gemmer væk","sætter tallerkener frem"],"a":"betaler for","r":"Når en forsikring dækker en skade, betaler den for det, der er gået i stykker."},
{"l":4800,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"l","variant":"authored","q":"Læs: 'Vand udvider sig, når det fryser, og derfor flyder is. Hvis isen sank, ville søer fryse fra bunden, og fisk ville ikke have et sted at overvintre.' Hvad er tekstens forklaring på, at fisk klarer vinteren?","o":["Fiskene svømmer op til overfladen, når det fryser","Isen lægger sig øverst, og der er vand under den","Vandet på bunden bliver varmet op af fiskene","Søer fryser ikke til om vinteren i Danmark"],"a":"Isen lægger sig øverst, og der er vand under den","r":"Teksten argumenterer ved at forestille sig det modsatte. Fordi is flyder, forbliver der flydende vand under isen."},
{"l":4820,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"f","variant":"authored","q":"Hvordan er en nyhedsartikel typisk bygget op?","o":["Det vigtigste står sidst, så læseren bliver spændt","Først kommer en lang beskrivelse af vejr og sted","Det vigtigste står først, og detaljerne kommer sidst","Først kommer en moral, og så følger selve historien"],"a":"Det vigtigste står først, og detaljerne kommer sidst","r":"I en nyhedsartikel kommer det vigtigste først, så læseren hurtigt ved, hvad der er sket. Det er det modsatte af en spændende fortælling."},
{"l":4839,"g":6,"b":2,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Hvilken form af 'at fortryde' passer: 'Har du ___, at du tog med?'","o":["fortrød","fortryder","fortrydende","fortrudt"],"a":"fortrudt","r":"Efter 'har' står den korte tillægsform: fortrudt. 'Fortrydende' er den lange tillægsform, der ikke kan stå her."},
{"l":4860,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Ministeren kom med et nyt 'udspil' om skolemad. Hvad betyder ordet her?","o":["et forslag til en løsning","et kort, man lægger på bordet","et skud mod mål i en kamp","en forsinkelse i en sag"],"a":"et forslag til en løsning","r":"I nyhederne er et udspil et forslag, som andre så kan tage stilling til. Ordet kommer fra spil."},
{"l":4879,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilket ord skal skrives med stort i: 'I denne uge skal vi læse alt på sin rette plads af H.C. Andersen.'?","o":["uge","alt","rette","plads"],"a":"alt","r":"Eventyret hedder 'Alt på sin rette plads'. I en titel får det første ord stort, også selvom det ikke er et navneord, og resten skrives med lille."},
{"l":4898,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilken stavemåde er rigtig? 'Jeg har læst den korte ___ af eventyret.'","o":["vertion","versjon","version","verssion"],"a":"version","r":"Ordet ender på -sion og ikke på -tion, selvom de to endelser lyder ens."},
{"l":4916,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"g","variant":"authored","q":"Cyklen tilhører Liam. Hvilket ord passer: 'Liam tror, at Aya har lånt ___ cykel.'","o":["sin","hendes","deres","hans"],"a":"hans","r":"'Sin' peger på grundleddet i samme sætning, her Aya i ledsætningen. Cyklen er Liams, så der skal stå 'hans'."},
{"l":4936,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning er skrevet rigtigt, når 'at' står foran et udsagnsord i navneform?","o":["Malthe glæder sig til at spille.","Malthe glæder sig til, at spille.","Malthe glæder, sig til at spille.","Malthe glæder sig, til at spille."],"a":"Malthe glæder sig til at spille.","r":"'At spille' er navneform og ikke en ledsætning, så der skal ikke komma."},
{"l":4957,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"o","variant":"authored","q":"Journalisten ville ikke afsløre sin 'kilde'. Hvad betyder ordet her?","o":["et sted, hvor vand kommer op af jorden","en person, der har givet oplysninger","en let berøring, der får en til at grine","en artikel, der står på forsiden"],"a":"en person, der har givet oplysninger","r":"En journalists kilde er den, der har fortalt noget til historien. Ordet kan også betyde en vandkilde."},
{"l":4974,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, hvis det er Aishas egne ord, der gengives?","o":["Aisha sagde: »at hun var sulten.«","Aisha sagde, »Jeg er sulten.«","Aisha sagde: »Jeg er sulten.«","Aisha sagde: Jeg er »sulten.«"],"a":"Aisha sagde: »Jeg er sulten.«","r":"Direkte tale gengiver ordene præcis, og anførselstegnene står om hele replikken. 'At hun var sulten' er indirekte tale."},
{"l":4994,"g":6,"b":3,"role":"reinforcement","insight":"conceptual_bridge","k":"s","variant":"authored","q":"Hvilket ord er stavet rigtigt? 'Vi lavede en ___ over klassens yndlingsfarver.'","o":["statestik","statistikk","stattistik","statistik"],"a":"statistik","r":"Ordet staves sta-ti-stik med i i de to sidste stavelser, og det ender på ét k."},
{"l":5010,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det at 'tale for døve øren'?","o":["at sige noget, som ingen vil lytte til","at tale alt for højt inde i et lille rum","at bruge ord, som ingen har hørt før","at fortælle en hemmelighed til en ven"],"a":"at sige noget, som ingen vil lytte til","r":"Udtrykket bruges, når man siger noget igen og igen, men de andre ikke tager det til sig."},
{"l":5031,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken form er rigtig i: 'Eiffeltårnet er ___ vartegn.'? Det handler om byen Paris.","o":["Pariss","Paris'","Paris's","Pari's"],"a":"Paris'","r":"Også bynavne på s får kun en apostrof i ejefald."},
{"l":5050,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad fortæller kolon læseren i 'Der var kun én løsning: Vi måtte gå tilbage.'?","o":["At nogen begynder at tale","At der kommer en opremsning","At der kommer en forklaring","At anden del er en ledsætning"],"a":"At der kommer en forklaring","r":"Kolon varsler noget, der følger: Her fortæller anden del, hvad løsningen var."},
{"l":5070,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad gør man, når man 'læser mellem linjerne'?","o":["læser meget hurtigt og springer over","læser teksten højt for en anden","skriver noter mellem tekstens linjer","forstår det, der ikke står direkte"],"a":"forstår det, der ikke står direkte","r":"I en tekst kan der ligge en mening, som ikke er skrevet ud. Den finder man ved at læse mellem linjerne."},
{"l":5090,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'På formularen skal du skrive din ___.'","o":["nationalitet","nationallitet","natonalitet","nationalitæt"],"a":"nationalitet","r":"Ordet indeholder 'nation' og ender på -itet. Der er kun ét l."},
{"l":5107,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilket ord er forkert skrevet med stort: 'I historie hørte vi om Kong Christian og Rundetårn i København.'?","o":["Christian","Kong","Rundetårn","København"],"a":"Kong","r":"Titler som konge og dronning skrives med lille foran navnet: kong Christian."},
{"l":5129,"g":6,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Lea så på billedet. Hun huskede, hvordan hun som seksårig havde stået på stranden med en stor is.' Hvad bruger forfatteren her?","o":["varsel","metafor","tilbageblik","besjæling"],"a":"tilbageblik","r":"Handlingen springer tilbage til noget, der skete tidligere. Det giver læseren baggrund for personen."},
{"l":5146,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'En blog på nettet påstår, at man kan lære et sprog på en uge med en særlig lydfil. Bloggen er skrevet af det firma, der sælger lydfilen. Der henvises til en undersøgelse, men ikke til, hvem der har lavet den. Alle de begejstrede kommentarer på siden er skrevet af brugere uden navn.' Hvorfor er der grund til at være skeptisk over for bloggen?","o":["Fordi den er skrevet på nettet og ikke i en bog","Fordi det er umuligt at bruge lydfiler til at lære noget","Fordi kommentarerne på siden er meget negative over for firmaet","Fordi firmaet tjener penge på det og ikke kan bevise det"],"a":"Fordi firmaet tjener penge på det og ikke kan bevise det","r":"Firmaet har en interesse i at sælge, og undersøgelsen kan ikke tjekkes. Det er de to svagheder ved kilden."},
{"l":5167,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at en ny lov 'træder i kraft'?","o":["at den begynder at gælde","at den bliver afskaffet","at den bliver diskuteret","at den bliver skrevet om"],"a":"at den begynder at gælde","r":"En lov kan være vedtaget, før den gælder. Den dag, den træder i kraft, skal alle følge den."},
{"l":5186,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Hun vil ___ sine svar en ekstra gang, inden hun afleverer.'","o":["kontrollerer","kontrollere","kontrolere","kontrolleret"],"a":"kontrollere","r":"Efter 'vil' står navnemåden. Ordet har dobbelt l, selvom 'kontrol' har ét."},
{"l":5206,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Muslinger renser havvand. En enkelt blåmusling kan filtrere flere liter vand i timen. Derfor har man i nogle danske fjorde sat liner ud, som muslinger kan vokse på. Når de bliver høstet, følger det kvælstof, de har optaget, med op af vandet.' Hvad er den dobbelte fordel ved metoden?","o":["Muslingerne vokser hurtigere, og linerne bliver længere","Fjorden bliver dybere, og vandet bliver mere salt","Vandet bliver renere, og kvælstof kommer op af fjorden","Kvælstof kommer ud i vandet, og fiskene får mere mad"],"a":"Vandet bliver renere, og kvælstof kommer op af fjorden","r":"Muslingerne filtrerer vandet, og høsten fjerner kvælstoffet. Begge dele hjælper fjorden."},
{"l":5226,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Et år uden sommer. I 1815 gik vulkanen Tambora i udbrud i det nuværende Indonesien. Asken spredte sig højt i luften over store dele af Jorden og skyggede for solen. Året efter blev det koldt i store dele af Europa og Nordamerika, og høsten slog fejl. Mange led sult, selvom de boede tusinder af kilometer fra vulkanen.' Hvad viser historien?","o":["At vulkaner er mest farlige for folk i Europa","At man bør bo langt væk fra vulkaner","At høsten altid slår fejl efter et koldt år","At et vulkanudbrud ét sted kan ramme folk langt væk"],"a":"At et vulkanudbrud ét sted kan ramme folk langt væk","r":"Et udbrud ét sted påvirkede folk på den anden side af kloden. Det er tekstens pointe."},
{"l":5246,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er budskabet i en tekst?","o":["Det, forfatteren gerne vil sige til læseren","Det sted og den tid, hvor handlingen foregår","Den person, der fortæller historien for os","Den allerførste sætning i hele teksten"],"a":"Det, forfatteren gerne vil sige til læseren","r":"Budskabet er den tanke, som teksten vil give videre til læseren. Det står sjældent direkte og må tit læses ud af handlingen."},
{"l":5267,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'hvem' i: 'Jeg ved ikke, hvem der kommer.'","o":["bindeord","stedord","biord","navneord"],"a":"stedord","r":"'Hvem' spørger efter en person, også her i en ledsætning. Det er et spørgende stedord."},
{"l":5287,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Skurken i filmen 'smider masken' til sidst. Hvad betyder det?","o":["han tager sit kostume af, fordi det er varmt","han flygter fra politiet i en stjålet bil","han viser, hvem han i virkeligheden er","han opgiver sin plan og beder om tilgivelse"],"a":"han viser, hvem han i virkeligheden er","r":"Masken står her for det, personen har foregivet at være. Nu kommer det sande jeg til syne."},
{"l":5300,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lokalavisen skriver: Modige elever redder kat ned fra tag. Nederst i artiklen står der, at katten sad på et cykelskur på to meter, og at eleverne brugte en stol.' Hvad er det, der ikke passer sammen i teksten?","o":["Katten er åbenbart mere modig end eleverne","Artiklen modsiger sig selv om, hvor katten sad","Eleverne brugte en stol i stedet for en stige","Overskriften lyder meget mere dramatisk, end det var"],"a":"Overskriften lyder meget mere dramatisk, end det var","r":"'Modige' og 'redder' lover noget stort, men et skur på to meter og en stol er ikke noget særligt. Derfor passer de ikke sammen."},
{"l":5316,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'I gamle dage havde hver by i Danmark sin egen tid, som man fandt ud fra solen. Urene i København og Esbjerg viste derfor ikke det samme. Det gjorde ikke noget, så længe folk rejste med hest og vogn. Men da togene kom, blev der brug for samme tid i hele landet.' Hvad kan man slutte om, hvorfor togene gjorde samme tid nødvendig?","o":["Køreplanerne skulle passe i alle byer","Togene kunne kun køre, når solen skinnede","Urene i Esbjerg gik hurtigere end i København","Hestevognene skulle nå frem før togene"],"a":"Køreplanerne skulle passe i alle byer","r":"Et tog skal køre på bestemte tidspunkter i mange byer. Det kan ikke lade sig gøre, hvis hver by har sit eget klokkeslæt."},
{"l":5335,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvad fortæller punktummet efter tallet i 'Vi går i 6. klasse.'?","o":["At sætningen slutter her","At tallet er et ordenstal","At tallet er et decimaltal","At der kommer en forklaring"],"a":"At tallet er et ordenstal","r":"Der skal læses 'sjette', og ordenstal skrevet med tal får punktum."},
{"l":5355,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'offentlig myndighed'?","o":["et privat firma, der tjener penge på at sælge varer","en forening, hvor man mødes med andre i fritiden","en del af staten eller kommunen, der må bestemme noget","en person, der er fyldt 18 år og derfor må stemme"],"a":"en del af staten eller kommunen, der må bestemme noget","r":"Myndigheder har magt til at træffe afgørelser for borgerne, for eksempel kommunen eller politiet."},
{"l":5376,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Danmark fik sin første kvindelige minister i 1924. Først i 1915 havde kvinder fået stemmeret. Mange mennesker havde kæmpet for det i årtier, med møder, breve og aviser. Det virkede længe, som om intet skete. Men retten til at stemme kom ikke af sig selv.' Hvad er tekstens pointe?","o":["At kvinder kun fik stemmeret på grund af avisernes hjælp","At alle var enige om kvinders stemmeret allerede fra start","At den første minister selv gav kvinderne deres ret","At forandringer ofte kræver lang og sej kamp"],"a":"At forandringer ofte kræver lang og sej kamp","r":"Teksten fremhæver årtiers arbejde og understreger til sidst, at retten ikke kom af sig selv."},
{"l":5392,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er en 'utopi'?","o":["et perfekt samfund, som aldrig kan blive virkeligt","et gammelt samfund, som er forsvundet for længst","et rigt samfund, som ligger på en fjern ø","et lille samfund, som lever af landbrug"],"a":"et perfekt samfund, som aldrig kan blive virkeligt","r":"Ordet kommer af græsk og betyder 'intet sted'. Man bruger det om en smuk idé, som ikke kan gennemføres."},
{"l":5411,"g":6,"b":4,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning om turen til stranden bruger kolon rigtigt?","o":["Vi pakkede: det vigtigste håndklæder, solcreme og vand.","Vi pakkede det vigtigste: håndklæder, solcreme og vand.","Vi: pakkede det vigtigste håndklæder, solcreme og vand.","Vi pakkede det vigtigste håndklæder: solcreme og vand."],"a":"Vi pakkede det vigtigste: håndklæder, solcreme og vand.","r":"'Det vigtigste' lægger op til noget, og kolon varsler listen, der fortæller, hvad det var."},
{"l":5432,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning om haven står i passiv, også kaldet lideform?","o":["Far vander haven hver dag.","Far har vandet haven.","Haven bliver vandet hver dag.","Haven er stor og grøn."],"a":"Haven bliver vandet hver dag.","r":"I passiv gør grundleddet ikke selv noget, men handlingen sker med det. Passiv kan dannes med 'blive' plus tillægsform."},
{"l":5452,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Læserbrev. Grundejerforeningen vil fælde 40 gamle egetræer for at bygge en cykelsti. De kalder det et grønt projekt! Skal vi virkelig ofre naturen for at redde naturen? Der findes en vej langs åen, som ville koste lidt mere, men som ikke kræver, at et eneste træ falder.' Hvad vil skribenten vise med udråbstegnet efter grønt projekt?","o":["At skribenten er begejstret for foreningens plan","At skribenten vil have læseren til at råbe højere","At skribenten vil have cykelstien malet grøn","At skribenten ikke synes, at det er grønt at fælde træer"],"a":"At skribenten ikke synes, at det er grønt at fælde træer","r":"Udråbstegnet viser, at skribenten er forarget. For skribenten giver det ikke mening at kalde det grønt at fælde 40 træer."},
{"l":5472,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Det koster ikke noget at blive medlem, står der med store bogstaver. Først i de små betingelser kan man læse, at der efter tre måneder trækkes 149 kroner om måneden, medmindre man opsiger aftalen skriftligt. Det gratis kan altså hurtigt blive det dyreste.' Hvad er det, teksten advarer imod?","o":["At stole på store bogstaver uden at læse resten","At læse små betingelser, fordi de er kedelige","At opsige en aftale skriftligt","At læse aftaler, der står med store bogstaver"],"a":"At stole på store bogstaver uden at læse resten","r":"Pointen er, at det vigtige gemmer sig med småt. Man skal læse det hele, før man siger ja."},
{"l":5491,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Mina fik et 'deja-vu' på skolens nye gang. Hvad er det?","o":["følelsen af at have glemt noget vigtigt","følelsen af at have oplevet det samme før","følelsen af at blive holdt øje med","følelsen af at være gået forkert"],"a":"følelsen af at have oplevet det samme før","r":"Deja-vu kommer af fransk 'déjà vu', der betyder 'allerede set'. Hjernen giver en stærk fornemmelse af at genkende øjeblikket."},
{"l":5509,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken ordklasse har 'siden' i: 'Læs siden færdig, inden du går.'","o":["bindeord","biord","navneord","forholdsord"],"a":"navneord","r":"'Siden' er her bestemt form af navneordet 'en side'. Det er ikke tidsordet 'siden'."},
{"l":5531,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad viser 'Det er ganske vist!', hvor en fjer ender som fem høns?","o":["Høns bliver let bange om natten","Gamle fortællinger er altid helt sande","Det er dumt at plukke sine egne fjer af","Rygter vokser, når de bliver fortalt videre"],"a":"Rygter vokser, når de bliver fortalt videre","r":"En lille hændelse vokser, hver gang den bliver fortalt videre. Eventyret driller vores lyst til at sladre."},
{"l":5551,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Forhandlingerne er 'gået i hårdknude'. Hvad betyder det?","o":["de er gået i stå og kommer ikke videre","de er endt med en god aftale for alle","de er blevet flyttet til en anden by","de er startet forfra med nye folk"],"a":"de er gået i stå og kommer ikke videre","r":"En hårdknude er en knude, som er svær at løse op. Derfor bruges ordet om en sag, der sidder fast."},
{"l":5570,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Personen graver gamle ting op og undersøger fortiden. Hvad er stavet rigtigt?","o":["arkeolog","arkæolog","akæolog","arkæulog"],"a":"arkæolog","r":"Ordet har r efter a og æ efter k. Det ender på -log."},
{"l":5588,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at være 'overbærende'?","o":["at være meget streng over for fejl","at være bedre end alle andre","at være tålmodig med andres fejl","at være i stand til at bære tungt"],"a":"at være tålmodig med andres fejl","r":"Den overbærende ser mildt på andres fejl og svagheder. Det har ikke noget med at bære ting at gøre."},
{"l":5606,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Orkesteret spillede en lang ___ af Carl Nielsen.'","o":["symphoni","simfoni","symfonni","symfoni"],"a":"symfoni","r":"Ordet har y efter s og f i stedet for ph på dansk. Det ender på -i med ét n."},
{"l":5627,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvem skrev teksten til 'Der er et yndigt land'?","o":["Adam Oehlenschläger","H.C. Andersen","N.F.S. Grundtvig","B.S. Ingemann"],"a":"Adam Oehlenschläger","r":"Adam Oehlenschläger skrev teksten, som nu er Danmarks nationalsang. Han var en af de store digtere i dansk romantik."},
{"l":5648,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder det, at skolelederen 'lagde vægt på', at alle skulle høres?","o":["at hun gjorde det hurtigere end andre","at hun mente, det var særlig vigtigt","at hun var bange for at blive misforstået","at hun selv ville høre alle eleverne"],"a":"at hun mente, det var særlig vigtigt","r":"At lægge vægt på noget er at fremhæve det som vigtigt. Vægten er her ikke noget, man kan måle."},
{"l":5666,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Find den rigtige stavemåde: 'Vi skar en stor ___ i skiver til pizzaen.'","o":["sjampinjon","champinjon","champignon","champingon"],"a":"champignon","r":"Ordet er fransk: sj-lyden skrives ch, og gn lyder som nj."},
{"l":5686,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad vil det sige at 'slå plat på' noget?","o":["at gøre grin med det på en plat måde","at ødelægge det med vilje","at vinde det i en lodtrækning","at udnytte det til sin egen fordel"],"a":"at udnytte det til sin egen fordel","r":"Den, der slår plat på noget, får en fordel ud af det, ofte på en lidt uærlig måde."},
{"l":5708,"g":6,"b":5,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad er et 'sisyfosarbejde'?","o":["et arbejde, der aldrig bliver færdigt","et arbejde, der giver meget høj løn","et arbejde, man udfører alene om natten","et arbejde, der kun tager få minutter"],"a":"et arbejde, der aldrig bliver færdigt","r":"I den græske myte skulle Sisyfos rulle en sten op ad et bjerg, men den trillede ned hver gang."},
{"l":5727,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Når en honningbi har fundet mad, vender den tilbage til boet og danser. Dansens retning fortæller de andre bier, hvor maden er, og dansens længde fortæller, hvor langt væk den ligger. På den måde kan hele boet hurtigt udnytte et godt sted.' Hvilken oplysning står der ikke i teksten?","o":["Hvornår bien begynder at danse","Hvor langt en bi kan flyve efter mad","Hvordan bien viser vej til maden","Hvordan bien fortæller om afstanden"],"a":"Hvor langt en bi kan flyve efter mad","r":"Teksten siger, hvor langt væk maden ligger, men ikke, hvor langt en bi kan flyve. De tre andre ting står der: Bien danser, når den er kommet hjem, og dansen viser både vej og afstand."},
{"l":5749,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"I grammatik har sætningsled både danske og latinske navne. Hvad hedder 'subjekt' på dansk?","o":["genstandsled","udsagnsled","grundled","hensynsled"],"a":"grundled","r":"Subjekt er det latinske navn for grundled, altså den eller det, der gør noget eller er noget i sætningen."},
{"l":5768,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Hidtil er det gået godt med projektet.' Hvilket udtryk kan stå i stedet for 'hidtil'?","o":["fra nu af","om lidt","for altid","indtil nu"],"a":"indtil nu","r":"'Hidtil' peger bagud i tiden og går frem til dette øjeblik. 'Fra nu af' peger den modsatte vej."},
{"l":5791,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"'Såfremt du bliver syg, skal du ringe til kontoret.' Hvilket almindeligt ord kan erstatte 'såfremt'?","o":["hvis","selvom","fordi","mens"],"a":"hvis","r":"'Såfremt' er et formelt ord, der indleder en betingelse ligesom 'hvis'. Det ses tit i aftaler og regler."},
{"l":5804,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Jonas talte trinene op til vippen. Elleve. Han kiggede ned på vandet, der pludselig så hårdt ud. Bag ham rømmede nogen sig. – Du kan godt gå ned igen, sagde hans bror, uden at lyde, som om han mente det.' Hvad føler Jonas mest sandsynligt?","o":["Han glæder sig til at vise sit spring","Han er bange, men tør ikke gå ned igen","Han er vred, fordi broren har sneget sig foran","Han er træt af at vente på sin tur"],"a":"Han er bange, men tør ikke gå ned igen","r":"Vandet ser pludselig hårdt ud, så han er bange. Broren står bag ham og mener det ikke, da han siger, at Jonas kan gå ned igen. Så er det svært at vende om."},
{"l":5826,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvorfor står 'vi' efter 'tager' i: 'I weekenden tager vi til Skagen.'?","o":["Sætningen er et spørgsmål","Sætningen er en ledsætning","Verbet skal stå på andenpladsen","Grundleddet skal stå sidst"],"a":"Verbet skal stå på andenpladsen","r":"I en dansk hovedsætning står verbet på andenpladsen. Begynder man med 'I weekenden', må grundleddet derfor rykke efter verbet."},
{"l":5848,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken verbalform passer med 'har': 'Hun har ___ alle opgaverne på to dage.'?","o":["lavede","lave","laver","lavet"],"a":"lavet","r":"Efter 'har' i førnutid står kort tillægsform: 'lavet'. 'Lavede' er datid og lyder næsten ens, men det kan ikke stå efter 'har'."},
{"l":5866,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Kommunen sender en 'pressemeddelelse' ud. Hvad er det?","o":["en tekst til medierne om en nyhed","et brev til borgerne om en regning","en kontrakt med et trykkeri i byen","en avis, som kommunen selv trykker"],"a":"en tekst til medierne om en nyhed","r":"Med en pressemeddelelse håber afsenderen, at journalister vil bringe historien. Den er skrevet af afsenderen selv og ikke af en uafhængig journalist."},
{"l":5886,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Som læge gennem tredive år kan jeg sige jer, at søvn er afgørende for børn.' Hvilken appelform er tydeligst?","o":["patos","etos","logos","kontrast"],"a":"etos","r":"Afsenderen bruger sin egen erfaring og sit fag til at virke troværdig. Det er etos."},
{"l":5903,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Feber og hoste er 'symptomer'. Hvad er et symptom?","o":["en medicin, der fjerner sygdom","en bakterie, der giver sygdom","et tegn på, at kroppen er syg","et sted, hvor syge bliver behandlet"],"a":"et tegn på, at kroppen er syg","r":"Et symptom er det, man kan mærke eller se, når man er syg. Lægen bruger symptomerne til at finde ud af, hvad der er galt."},
{"l":5925,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Find ledsætningen, der fortæller, hvad mor sagde: 'Før bussen kørte, sagde mor, at vi skulle skynde os.'","o":["Før bussen kørte","sagde mor","vi skulle skynde os","at vi skulle skynde os"],"a":"at vi skulle skynde os","r":"'At vi skulle skynde os' fortæller, hvad mor sagde. 'Før bussen kørte' er også en ledsætning, men den fortæller, hvornår det skete."},
{"l":5947,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Jakken er Antons egen. Hvilket stedord skal stå: 'Anton hentede ___ jakke i garderoben.'?","o":["sin","hans","dens","deres"],"a":"sin","r":"'Sin' viser tilbage til sætningens grundled, altså Anton selv. 'Hans jakke' ville betyde en anden drengs jakke."},
{"l":5967,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt ind: 'Stormen har ___ drivhuset.'","o":["ødelakt","ødelagt","ødelæggt","ødlagt"],"a":"ødelagt","r":"Tillægsformen af 'ødelægge' skifter æ til a og skrives med g, selvom det lyder som k."},
{"l":5986,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord har samme ordklasse som 'kritik'?","o":["kritisk","kritisere","kritiker","kritiseret"],"a":"kritiker","r":"'Kritik' og 'kritiker' er begge navneord: en kritik, en kritiker. 'Kritisk' er et tillægsord, og 'kritisere' er et udsagnsord."},
{"l":6000,"g":7,"b":1,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Museets skilt: Sværdet blev fundet i 1902. Det stammer sandsynligvis fra vikingetiden, men nyere undersøgelser tyder på, at det kan være yngre.' Hvad er sikkert ifølge skiltet?","o":["Hvornår sværdet blev smedet","Hvem der smedede sværdet","Hvad sværdet blev brugt til","Hvornår sværdet blev fundet"],"a":"Hvornår sværdet blev fundet","r":"Ordene 'sandsynligvis', 'tyder på' og 'kan' markerer usikkerhed om alderen. Kun fundåret står uden forbehold."},
{"l":6016,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I biologi er en bakterie og en elefant begge 'organismer'. Hvad er en organisme?","o":["et levende væsen","et dødt stof i jorden","et redskab i laboratoriet","et lag i atmosfæren"],"a":"et levende væsen","r":"Alt, der lever, er en organisme, uanset om det er en enkelt celle eller et stort dyr."},
{"l":6038,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilken sætning er passiv udgave af: 'Yusuf vaskede bilen.'?","o":["Bilen bliver vasket af Yusuf.","Bilen blev vasket af Yusuf.","Bilen vaskes af Yusuf.","Yusuf blev vasket af bilen."],"a":"Bilen blev vasket af Yusuf.","r":"I passiv bliver genstandsleddet 'bilen' til grundled, og den, der handler, kan nævnes med 'af'. 'Vaskede' står i datid, så den passive sætning skal også stå i datid: 'blev vasket'."},
{"l":6058,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Hvad er rigtigt i sætningen? 'Du ___ ikke at vente på mig, hvis du har travlt.'","o":["behøve","behøves","behøver","behøvver"],"a":"behøver","r":"Sætningen står i nutid med 'du' som grundled, så der skal -r på: du behøver. 'Behøves' passer kun i sætninger som 'det behøves ikke'."},
{"l":6079,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Noah til sin mor: Alle mine venner har længere sengetid end mig. Hvis du giver mig lov til at blive oppe, får jeg bedre karakterer, for så bliver jeg mindre stresset over at være udenfor.' Hvad er svagest ved Noahs argument?","o":["Han nævner ikke, hvor mange af hans venner der må blive oppe","Han nævner ikke, hvornår hans venner står op","Han nævner ikke, hvilke fag han vil blive bedre i","Han viser ikke, at sen sengetid giver bedre karakterer"],"a":"Han viser ikke, at sen sengetid giver bedre karakterer","r":"Han siger, at senere sengetid giver bedre karakterer, men han giver ingen grund til at tro på det. At han lover det, beviser ikke noget."},
{"l":6098,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"En forsker skriver en 'kronik' i avisen. Hvad er det?","o":["en længere artikel med et synspunkt","en oversigt over dagens tv-programmer","en historisk bog om konger og krige","en kort nyhed fra et nyhedsbureau"],"a":"en længere artikel med et synspunkt","r":"I en kronik argumenterer en skribent uden for avisen for et synspunkt. Ordet må ikke forveksles med 'krønike', som er en fortælling om historiske begivenheder."},
{"l":6112,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Efter ombygningen er skolens bibliotek blevet et læringsrum med sækkestole. Bøgerne er flyttet ned i kælderen, så der er bedre plads til fællesskab. Det må man da sige er fremskridt.' Hvordan skal den sidste sætning forstås?","o":["Som en ærlig ros af de nye sækkestole","Som en ironisk kritik af ombygningen","Som en saglig oplysning om kælderen","Som en opfordring til at læse flere bøger"],"a":"Som en ironisk kritik af ombygningen","r":"Et bibliotek uden bøger i nærheden er ikke et oplagt fremskridt. Skribentens 'det må man da sige' er derfor spydigt ment."},
{"l":6134,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Graf over bymuseets besøg: I 2019 kom 8.000 gæster, i 2020 kom 4.000, og i 2021 kom 7.500. Museets leder skriver: Vores nye udstilling har næsten fordoblet besøgstallet.' Hvad er problemet med lederens påstand?","o":["Antallet af gæster steg slet ikke fra 2020 til 2021","Grafen viser kun to år, så man kan ikke se udviklingen","Lederen sammenligner kun med det dårlige år 2020","Lederen har regnet forkert med tallene for 2020 og 2021"],"a":"Lederen sammenligner kun med det dårlige år 2020","r":"I 2019 kom der flere end i 2021. Lederen bruger kun det dårlige år 2020, så det ser bedre ud, end det er."},
{"l":6151,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et dyr bruger 'kamuflage'. Hvad gør det?","o":["det jager sammen i flok","det sover hele vinteren","det skræmmer fjender med høje lyde","det går i ét med omgivelserne"],"a":"det går i ét med omgivelserne","r":"Kamuflage gør et dyr svært at få øje på. Det kan være en pels eller hud med samme farve som omgivelserne."},
{"l":6175,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Læs: 'Det er på tide, at skolen indfører længere frikvarterer. Vi kan ikke koncentrere os, når vi kun får ti minutter.' Hvilken genre passer bedst?","o":["debatindlæg","anmeldelse","reportage","nyhedsartikel"],"a":"debatindlæg","r":"Skribenten fremsætter en holdning og argumenterer for den. Det er det, et debatindlæg skal."},
{"l":6196,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Varer fra lande uden for EU kan blive pålagt 'told'. Hvad er det?","o":["et forbud mod at sælge varerne i butikker","en afgift på varer, der føres ind i landet","en rabat til dem, der køber mange varer","en pligt til at sende varerne tilbage igen"],"a":"en afgift på varer, der føres ind i landet","r":"Told gør udenlandske varer dyrere. Det er noget andet end moms, som ligger på de fleste varer, uanset hvor de kommer fra."},
{"l":6203,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket sammensat ord har bindebogstavet -s- mellem de to led?","o":["husdyr","håndtaske","arbejdsdag","skolegård"],"a":"arbejdsdag","r":"I 'arbejdsdag' binder et -s- de to led sammen. I 'husdyr' hører s'et til ordet 'hus', og e'et i 'skolegård' hører til ordet 'skole'."},
{"l":6226,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad er temaet i en novelle?","o":["Det sted, hvor handlingen udspiller sig","Den person, der fortæller historien","Det, der sker i handlingen, trin for trin","Det overordnede emne, f.eks. venskab"],"a":"Det overordnede emne, f.eks. venskab","r":"Temaet er det overordnede emne, teksten kredser om, f.eks. venskab, svigt eller frihed. Det er ikke det samme som handlingen."},
{"l":6244,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Svømmeklubbens brev: Vores nye træningshold giver alle medlemmer bedre muligheder. Vejen til træning vil for nogle blive en lille smule længere. I det store billede er det en gevinst for alle.' Hvad gør brevet med ulemperne?","o":["Det får dem til at lyde mindre, end de er","Det skjuler dem helt for læseren","Det regner dem ud i præcise tal","Det overdriver dem for at virke ærligt"],"a":"Det får dem til at lyde mindre, end de er","r":"'En lille smule' og 'i det store billede' får ulempen til at lyde lille, og brevet siger ikke, hvor meget længere vejen bliver."},
{"l":6266,"g":7,"b":2,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Sæt det rigtige ord ind: 'Det var en ___ opgave, som tog hele timen.'","o":["vansklig","vanskelig","vanskellig","vansgelig"],"a":"vanskelig","r":"Ordet har et e foran -lig, og der er kun ét l."},
{"l":6292,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"s","variant":"authored","q":"Vælg stavemåden: 'Efter nogle år på værkstedet blev Emil ___ og åbnede sit eget firma.'","o":["selvstænding","selstændig","selvstændig","selvstendig"],"a":"selvstændig","r":"Husk v'et i 'selv' og æ'et i '-stændig'. Ordet ender på -ig."},
{"l":6300,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Årets skolefest har altid været i gymnastiksalen, og sådan skal det selvfølgelig blive ved med at være. Vi behøver ikke at diskutere det.' Hvad bygger skribenten sit argument på?","o":["At der er god plads i gymnastiksalen","At andre skoler gør det samme","At eleverne selv ønsker det","At sådan har man altid gjort"],"a":"At sådan har man altid gjort","r":"'Altid' og 'selvfølgelig' står i stedet for en grund. At noget er gjort længe, siger ikke, at det er bedst."},
{"l":6320,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvilken sætning er rigtig, når der står en forklaring om byen lige efter dens navn?","o":["Odense, den største by på Fyn, er H.C. Andersens fødeby.","Odense, den største by på Fyn er H.C. Andersens fødeby.","Odense den største by på Fyn, er H.C. Andersens fødeby.","Odense den største by, på Fyn er H.C. Andersens fødeby."],"a":"Odense, den største by på Fyn, er H.C. Andersens fødeby.","r":"En forklarende tilføjelse efter et navn skal have komma på begge sider."},
{"l":6343,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Fra næste år skal eleverne selv feje klasselokalet. Det lærer os ansvar, siger ledelsen. Det sparer også 200.000 kroner om året, står der med småt på side 9 i budgettet.' Hvad antyder skribenten?","o":["At eleverne lærer ansvar af at feje selv","At pengene måske er den egentlige grund","At budgettet er fyldt med regnefejl","At ledelsen har gemt budgettet for eleverne"],"a":"At pengene måske er den egentlige grund","r":"Ledelsen siger højt, at det handler om ansvar, mens besparelsen står 'med småt' på side 9. Det får en til at tvivle på, om ansvar er den rigtige grund."},
{"l":6361,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"I samfundsfag bruges ordet 'socialisering' om børn og unge. Hvad betyder det her?","o":["at de bruger meget tid på deres sociale medier","at de får flere venner i en ny klasse","at de lærer, hvordan man opfører sig blandt andre","at de flytter hjemmefra som meget unge"],"a":"at de lærer, hvordan man opfører sig blandt andre","r":"Det sker hele tiden gennem familie, skole og venner: Man ser, hvad de andre gør, og lærer, hvad der er i orden."},
{"l":6383,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Et land i FN's Sikkerhedsråd bruger sin 'vetoret'. Hvad gør landet?","o":["støtter et forslag sammen med de andre lande","melder sig ud af FN med øjeblikkelig virkning","udsætter mødet til næste dag i Sikkerhedsrådet","standser en beslutning, selv om andre er for den"],"a":"standser en beslutning, selv om andre er for den","r":"'Veto' er latin og betyder 'jeg forbyder'. Den, der har vetoret, kan alene blokere en beslutning."},
{"l":6400,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"t","variant":"authored","q":"Hvordan skriver man to en kvart kilo mel i en opskrift?","o":["2,25 kg mel","2,25 kg. mel","2.25 kg mel","2.25 kg. mel"],"a":"2,25 kg mel","r":"Decimaltal skrives med komma på dansk, og 'kg' skrives uden punktum."},
{"l":6421,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad laver en 'lobbyist'?","o":["tager imod gæster i en stor hotelreception","prøver at påvirke politikernes beslutninger","tæller stemmer efter valget til Folketinget","skriver taler til kongehuset"],"a":"prøver at påvirke politikernes beslutninger","r":"En lobbyist arbejder for en organisation eller et firma. Navnet kommer af forhallen, 'lobbyen', hvor man mødte politikerne."},
{"l":6442,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Hele sommeren havde vi bygget på huset i træet. Efter ferien lå der en seddel på gulvet med Mikkels skrift: Jeg tror, jeg er blevet for gammel til det her. Jeg læste den to gange. Så klatrede jeg ned med hammeren.' Hvad handler uddraget i bund og grund om?","o":["At et træhus er blevet for farligt","At Mikkel er flyttet til en anden by","At et venskab er ved at forandre sig","At fortælleren er blevet træt af Mikkel"],"a":"At et venskab er ved at forandre sig","r":"Træhuset står for det, de havde sammen. Sedlen og fortællerens stille reaktion viser, at noget mellem dem er ved at slutte."},
{"l":6464,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Et gammelt symbol viser et kors, et anker og et hjerte. De tre står for tro, håb og kærlighed. Hvad står ankeret for?","o":["tro","kærlighed","fred","håb"],"a":"håb","r":"Korset står for tro, og hjertet står for kærlighed. Ankeret holder et skib fast i uvejr, og derfor står det for håb."},
{"l":6486,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Lydbølger kan ikke bevæge sig i tomt rum, fordi der intet stof er til at føre dem videre. I film om rumfart brummer rumskibenes motorer alligevel tydeligt.' Hvad er underforstået om filmene?","o":["De har lyd med, selv om det er forkert","De bruger rigtige optagelser fra rummet","De er optaget i et rum uden luft","De er lavet, før man kendte til lydbølger"],"a":"De har lyd med, selv om det er forkert","r":"'Alligevel' viser, at filmene gør noget, der ikke kan ske i virkeligheden. Lyden er med, fordi den giver stemning."},
{"l":6500,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Enten stemmer I for den nye hal, eller også er I ligeglade med børnene.' Hvad er fejlen i udsagnet?","o":["Det siger ikke, hvad den nye hal skal koste","Det påstår, at der kun findes to muligheder","Det er henvendt til dem, der er ligeglade","Det nævner, at der snart er en afstemning"],"a":"Det påstår, at der kun findes to muligheder","r":"Man kan godt holde af børn og alligevel være imod hallen. Det kaldes et falsk dilemma."},
{"l":6515,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"f","variant":"authored","q":"Hvad kaldes en gruppe linjer, der hører sammen i et digt, ligesom et afsnit i en fortælling?","o":["replik","kapitel","strofe","slogan"],"a":"strofe","r":"Digte er delt op i strofer, som adskilles med en tom linje."},
{"l":6533,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Sæt det rigtige ord ind: 'Medicinen havde en positiv ___.'","o":["effektiv","effektivt","effektivisere","effekt"],"a":"effekt","r":"Efter 'en positiv' mangler der et navneord. 'Effektiv' er et tillægsord, og 'effektivisere' er et udsagnsord."},
{"l":6554,"g":7,"b":3,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"En vestjyde siger 'æ hus' og ikke 'huset'. Hvad er det et eksempel på?","o":["dialekt","sociolekt","slang","fagsprog"],"a":"dialekt","r":"En dialekt hører til et geografisk område, for eksempel Vestjylland eller Bornholm. En sociolekt hører derimod til en gruppe i samfundet."},
{"l":6576,"g":7,"b":4,"role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvad er hensynsleddet i: 'Læreren viste klassen et kort over Norden.'?","o":["Læreren","klassen","viste","et kort over Norden"],"a":"klassen","r":"Spørg: Hvem blev kortet vist for? Det blev klassen. Kortet er det, der bliver vist, og det er genstandsleddet."}
]$$::jsonb) AS e
JOIN (VALUES
  ('s', 'stavning', 'recall', 'factual', 'surface_association'),
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('t', 'tegnsætning', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'comprehension', 'conceptual', 'surface_association'),
  ('f', 'litteratur', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
